Let me restructure march to return the final color including background:
```glsl
vec3 march(vec3 ro, vec3 rd) {
    vec3 p = ro;
    vec3 v = rd;
    float L2 = dot(cross(p,v), cross(p,v));
    vec3 acc = vec3(0.0);
    float trans = 1.0;
    bool escaped = false, captured = false;
    float steps = 0.0;
    for (int i = 0; i < MAX_STEPS; i++) {
        if (i >= uSteps) break;
        float r = length(p);
        if (r < 2.0) { captured = true; break; }
        if (r > 40.0 && dot(p,v) > 0.0) { escaped = true; break; }
        float dt = uStepScale * max(r, 1.0);
        // RK4
        vec3 np = rk4(p, v, dt, L2, v);  // returns new p, updates v
        // disk accumulation at midpoint
        vec3 pm = (p + np) * 0.5;
        float rmid = length(pm);
        float density = diskDensity(pm);
        if (density > 0.0) {
            // physical step length
            float rdot = dot(pm, v)/rmid;
            float vphys = sqrt(max(rdot*rdot/(1.0-2.0/rmid) + dot(v,v) - rdot*rdot, 0.0));
            float ds = vphys * dt;
            vec3 em = diskEmission(pm, v);
            float sigma = density * uDiskOpacity;
            float alpha = 1.0 - exp(-sigma * ds);
            acc += trans * em * alpha;
            trans *= (1.0 - alpha);
            if (trans < 0.002) break;
        }
        p = np;
        steps += 1.0;
    }
    vec3 col = acc;
    if (escaped) {
        col += trans * background(normalize(v));
    }
    // captured → black (acc already has whatever disk emission before capture)
    return col;
}
```

Wait, there's an issue with the RK4 and updating v. Let me write the RK4 properly. The ODE is:
dp/dλ = v
dv/dλ = a(p, v) = -3 L² p / r⁵

RK4:
```
k1p = v
k1v = a(p, v)
k2p = v + 0.5*dt*k1v
k2v = a(p + 0.5*dt*k1p, v + 0.5*dt*k1v)
k3p = v + 0.5*dt*k2v
k3v = a(p + 0.5*dt*k2p, v + 0.5*dt*k2v)
k4p = v + dt*k3v
k4v = a(p + dt*k3p, v + dt*k3v)
p_new = p + dt/6*(k1p + 2k2p + 2k3p + k4p)
v_new = v + dt/6*(k1v + 2k2v + 2k3v + k4v)
```

where a(p,v) = -3*L2*p/pow(length(p),5).

