export const PARAM_KEYS = PARAMS.map(p => p.key);

// Quality tiers: integration steps, adaptive step scale, pixel-ratio cap, bloom resolution.
export const QUALITY = {
  standard:  { steps: 300, stepScale: 0.05,  dpr: 1.0, bloomRes: 0.5, label: 'Standard' },
  high:      { steps: 512, stepScale: 0.05,  dpr: 1.5, bloomRes: 1.0, label: 'High' },
  cinematic: { steps: 768, stepScale: 0.045, dpr: 2.0, bloomRes: 1.0, label: 'Cinematic' },
};
export const QUALITY_ORDER = ['standard', 'high', 'cinematic'];

export function defaultState() {
  const params = {};
  for (const p of PARAMS) params[p.key] = p.def;
  return {
    params,
    quality: 'high',
    debug: 0,
    cinematic: false,
    playing: true,
    music: false,
    preset: 0, // last camera preset index
  };
}

const LS_KEY = 'gargantua.state.v1';

// Merge saved/URL state over defaults. Returns { state, urlShot }.
export function loadState() {
  const state = defaultState();
  // 1) localStorage
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) {
      const saved = JSON.parse(raw);
      if (saved.params) for (const k of PARAM_KEYS) if (typeof saved.params[k] === 'number') state.params[k] = saved.params[k];
      if (QUALITY_ORDER.includes(saved.quality)) state.quality = saved.quality;
      if (typeof saved.debug === 'number') state.debug = saved.debug;
      if (typeof saved.cinematic === 'boolean') state.cinematic = saved.cinematic;
      if (typeof saved.playing === 'boolean') state.playing = saved.playing;
      if (typeof saved.music === 'boolean') state.music = saved.music;
      if (typeof saved.preset === 'number') state.preset = saved.preset;
    }
  } catch (e) { /* ignore corrupt state */ }

  // 2) URL query overrides (highest priority) — enables screenshot automation
  const url = new URLSearchParams(location.search);
  let shot = null;
  if (url.has('shot')) shot = url.get('shot');
  if (url.has('quality') && QUALITY_ORDER.includes(url.get('quality'))) state.quality = url.get('quality');
  if (url.has('debug')) { const d = parseInt(url.get('debug'), 10); if (!isNaN(d)) state.debug = d; }
  if (url.has('cinematic')) state.cinematic = url.get('cinematic') === '1';
  if (url.has('music')) state.music = url.get('music') === '1';
  if (url.has('t')) { const t = parseFloat(url.get('t')); if (!isNaN(t)) state.simTime = t; }
  for (const k of PARAM_KEYS) {
    if (url.has(k)) { const v = parseFloat(url.get(k)); if (!isNaN(v)) state.params[k] = v; }
  }
  // camera overrides
  state.cam = {};
  if (url.has('az')) state.cam.az = parseFloat(url.get('az'));
  if (url.has('el')) state.cam.el = parseFloat(url.get('el'));
  if (url.has('dist')) state.cam.dist = parseFloat(url.get('dist'));
  if (url.has('fov')) state.params.fov = parseFloat(url.get('fov'));
  return { state, urlShot: shot };
}

export function saveState(state) {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify({
      params: state.params,
      quality: state.quality,
      debug: state.debug,
      cinematic: state.cinematic,
      playing: state.playing,
      music: state.music,
      preset: state.preset,
    }));
  } catch (e) { /* storage may be unavailable */ }
}

// GARGANTUA — camera rig: 4 view presets, cinematic loop, smooth transitions.
// Spherical convention: pos = dist * (cos(el)cos(az), cos(el)sin(az), sin(el)); el=0 is edge-on.

export const PRESETS = [
  { name: 'Classic',     az: 0.0,  el: 18, dist: 28, fov: 60 },
  { name: 'Overhead',    az: 0.0,  el: 72, dist: 32, fov: 55 },
  { name: 'Photon Ring', az: 0.0,  el: 3,  dist: 17, fov: 50 },
  { name: 'Orbit',       az: 40,   el: 32, dist: 24, fov: 60 },
];

const DEG = Math.PI / 180;

function sphericalToVec3(az, el, dist) {
  const e = el * DEG, a = az * DEG;
  return [dist * Math.cos(e) * Math.cos(a), dist * Math.cos(e) * Math.sin(a), dist * Math.sin(e)];
}

function vec3ToSpherical(x, y, z) {
  const dist = Math.hypot(x, y, z);
  const el = Math.asin(Math.max(-1, Math.min(1, z / dist))) / DEG;
  const az = Math.atan2(y, x) / DEG;
  return { az, el, dist };
}

const easeInOut = t => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

export class CameraRig {
  constructor(camera, controls) {
    this.camera = camera;
    this.controls = controls;
    this.mode = 'orbit';            // 'orbit' | 'transition' | 'cinematic'
    this.trans = null;              // {from, to, t, dur}
    this.cineT = 0;
    this.fovTarget = 60;
  }

  currentSpherical() {
    const p = this.camera.position;
    return vec3ToSpherical(p.x, p.y, p.z);
  }

  applySpherical(az, el, dist) {
    const [x, y, z] = sphericalToVec3(az, el, dist);
    this.camera.position.set(x, y, z);
    this.camera.lookAt(0, 0, 0);
    this.controls.target.set(0, 0, 0);
    this.controls.update();
  }

  setPreset(i) {
    const p = PRESETS[i];
    if (!p) return;
    this.mode = 'transition';
    this.trans = {
      from: this.currentSpherical(),
      to: { az: p.az, el: p.el, dist: p.dist },
      t: 0, dur: 1.6,
    };
    this.fovTarget = p.fov;
  }

  setCinematic(on) {
    if (on) {
      this.mode = 'cinematic';
      this.cineT = 0;
    } else {
      this.mode = 'orbit';
    }
  }

  // Cinematic path: slow orbit + elevation/dolly drift (smooth, non-repeating feel).
  cineSpherical(t) {
    const az = t * 0.12;
    const el = 22 + 16 * Math.sin(t * 0.06);
    const dist = 25 + 7 * Math.sin(t * 0.043 + 1.0);
    return { az, el, dist };
  }

  update(dt) {
    // fov easing
    const curFov = this.camera.fov;
    if (Math.abs(curFov - this.fovTarget) > 0.05) {
      this.camera.fov = curFov + (this.fovTarget - curFov) * Math.min(1, dt * 4);
      this.camera.updateProjectionMatrix();
    }

    if (this.mode === 'cinematic') {
      this.cineT += dt;
      const s = this.cineSpherical(this.cineT);
      this.applySpherical(s.az, s.el, s.dist);
    } else if (this.mode === 'transition' && this.trans) {
      const tr = this.trans;
      tr.t += dt;
      const k = easeInOut(Math.min(1, tr.t / tr.dur));
      // shortest-path azimuth lerp
      let dAz = tr.to.az - tr.from.az;
      if (dAz > 180) dAz -= 360;
      if (dAz < -180) dAz += 360;
      const az = tr.from.az + dAz * k;
      const el = tr.from.el + (tr.to.el - tr.from.el) * k;
      const dist = tr.from.dist + (tr.to.dist - tr.from.dist) * k;
      this.applySpherical(az, el, dist);
      if (tr.t >= tr.dur) this.mode = 'orbit';
    }
    // 'orbit': OrbitControls drives the camera; nothing to do.
  }
}

// GARGANTUA — optional ambient music (WebAudio). Loads audio/ambient.wav, loops it.
// Browsers require a user gesture to start audio; we arm on first interaction.

export class AmbientAudio {
  constructor(url = 'audio/ambient.wav') {
    this.url = url;
    this.ctx = null;
    this.gain = null;
    this.source = null;
    this.buffer = null;
    this.enabled = false;
    this.ready = false;
    this._armed = false;
  }

  _ensureCtx() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AC();
      this.gain = this.ctx.createGain();
      this.gain.gain.value = 0.0;
      this.gain.connect(this.ctx.destination);
    }
  }

  async load() {
    try {
      this._ensureCtx();
      const res = await fetch(this.url);
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const arr = await res.arrayBuffer();
      this.buffer = await this.ctx.decodeAudioData(arr);
      this.ready = true;
    } catch (e) {
      console.warn('[GARGANTUA] ambient audio unavailable:', e.message);
      this.ready = false;
    }
  }

  _startSource() {
    if (!this.buffer || this.source) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.buffer;
    src.loop = true;
    src.connect(this.gain);
    src.start(0);
    this.source = src;
  }

  setEnabled(on) {
    this.enabled = on;
    if (on) {
      this._ensureCtx();
      if (this.ctx.state === 'suspended') this.ctx.resume();
      this._startSource();
      const t = this.ctx.currentTime;
      this.gain.gain.cancelScheduledValues(t);
      this.gain.gain.setTargetAtTime(0.5, t, 1.2); // gentle fade-in
    } else if (this.gain) {
      const t = this.ctx.currentTime;
      this.gain.gain.cancelScheduledValues(t);
      this.gain.gain.setTargetAtTime(0.0, t, 0.6);
    }
  }

  toggle() {
    this.setEnabled(!this.enabled);
    return this.enabled;
  }
}

// GARGANTUA — HUD: builds the DOM overlay (sliders, debug views, presets, toggles, status).
import { PARAMS, QUALITY, QUALITY_ORDER } from './params.js';
import { PRESETS } from './camera.js';

const DEBUG_NAMES = ['Beauty', 'Steps', 'Deflection', 'Density', 'Doppler', 'Redshift', 'Temp', 'Transmittance', 'Min Radius', 'Photon Sphere'];

export function buildHUD(root, state, handlers) {
  const el = (tag, cls, html) => {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html != null) e.innerHTML = html;
    return e;
  };

  const hud = el('div', 'hud');
  root.appendChild(hud);

  // ---- top-left status ----
  const top = el('div', 'hud-top');
  const title = el('div', 'hud-title', 'GARGANTUA');
  const subtitle = el('div', 'hud-sub', 'Schwarzschild Black Hole Raytracer');
  const status = el('div', 'hud-status', '—');
  top.append(title, subtitle, status);
  hud.appendChild(top);

  // ---- panel toggle button ----
  const toggleBtn = el('button', 'hud-toggle', '☰ Controls');
  hud.appendChild(toggleBtn);

  // ---- right panel ----
  const panel = el('div', 'hud-panel');
  hud.appendChild(panel);

  const section = (label) => {
    const s = el('div', 'hud-section');
    s.appendChild(el('div', 'hud-section-title', label));
    panel.appendChild(s);
    return s;
  };

  // parameter sliders, grouped
  const groups = {};
  for (const p of PARAMS) {
    if (!groups[p.group]) groups[p.group] = section(p.group);
    const row = el('div', 'hud-row');
    const lab = el('label', 'hud-label', p.label);
    const val = el('span', 'hud-val', fmt(p.def, p.step));
    const input = el('input');
    input.type = 'range';
    input.min = p.min; input.max = p.max; input.step = p.step;
    input.value = state.params[p.key];
    val.textContent = fmt(state.params[p.key], p.step);
    input.addEventListener('input', () => {
      const v = parseFloat(input.value);
      val.textContent = fmt(v, p.step);
      handlers.onParam(p.key, v);
    });
    row.append(lab, input, val);
    groups[p.group].appendChild(row);
  }

  // quality
  const qSec = section('Quality');
  const qRow = el('div', 'hud-btnrow');
  for (const q of QUALITY_ORDER) {
    const b = el('button', 'hud-btn' + (q === state.quality ? ' active' : ''), QUALITY[q].label);
    b.dataset.q = q;
    b.addEventListener('click', () => { handlers.onQuality(q); syncQuality(); });
    qRow.appendChild(b);
  }
  qSec.appendChild(qRow);

  // debug views
  const dSec = section('Debug View');
  const dRow = el('div', 'hud-btnrow hud-debugrow');
  for (let i = 0; i <= 9; i++) {
    const b = el('button', 'hud-btn hud-debug' + (i === state.debug ? ' active' : ''), String(i));
    b.title = DEBUG_NAMES[i];
    b.dataset.d = i;
    b.addEventListener('click', () => { handlers.onDebug(i); syncDebug(); });
    dRow.appendChild(b);
  }
  dSec.appendChild(dRow);
  const dName = el('div', 'hud-debugname', DEBUG_NAMES[state.debug]);
  dSec.appendChild(dName);

  // presets
  const pSec = section('Camera Presets');
  const pRow = el('div', 'hud-btnrow');
  PRESETS.forEach((pr, i) => {
    const b = el('button', 'hud-btn' + (i === state.preset ? ' active' : ''), pr.name);
    b.dataset.p = i;
    b.addEventListener('click', () => { handlers.onPreset(i); syncPreset(); });
    pRow.appendChild(b);
  });
  pSec.appendChild(pRow);

  // toggles
  const tSec = section('Playback');
  const tRow = el('div', 'hud-btnrow');
  const playBtn = el('button', 'hud-btn' + (state.playing ? ' active' : ''), state.playing ? '⏸ Pause' : '▶ Play');
  playBtn.addEventListener('click', () => { handlers.onPlay(); syncPlay(); });
  const cineBtn = el('button', 'hud-btn' + (state.cinematic ? ' active' : ''), '🎬 Cinematic');
  cineBtn.addEventListener('click', () => { handlers.onCinematic(); syncCine(); });
  const musicBtn = el('button', 'hud-btn' + (state.music ? ' active' : ''), '🎵 Music');
  musicBtn.addEventListener('click', () => { handlers.onMusic(); syncMusic(); });
  const resetBtn = el('button', 'hud-btn', '↺ Reset');
  resetBtn.addEventListener('click', () => handlers.onReset());
  tRow.append(playBtn, cineBtn, musicBtn, resetBtn);
  tSec.appendChild(tRow);

  // ---- bottom help ----
  const help = el('div', 'hud-help',
    '<b>Keys</b> Space play · C cinematic · 1–4 presets · 0–9 debug · Q quality · H hide · M music · S screenshot · R reset · F fullscreen · drag orbit · wheel zoom');
  hud.appendChild(help);

  // ---- sync helpers ----
  function syncQuality() {
    qRow.querySelectorAll('.hud-btn').forEach(b => b.classList.toggle('active', b.dataset.q === state.quality));
  }
  function syncDebug() {
    dRow.querySelectorAll('.hud-btn').forEach(b => b.classList.toggle('active', +b.dataset.d === state.debug));
    dName.textContent = DEBUG_NAMES[state.debug];
  }
  function syncPreset() {
    pRow.querySelectorAll('.hud-btn').forEach(b => b.classList.toggle('active', +b.dataset.p === state.preset));
  }
  function syncPlay() { playBtn.textContent = state.playing ? '⏸ Pause' : '▶ Play'; playBtn.classList.toggle('active', state.playing); }
  function syncCine() { cineBtn.classList.toggle('active', state.cinematic); }
  function syncMusic() { musicBtn.classList.toggle('active', state.music); }

  let panelOpen = true;
  function togglePanel() {
    panelOpen = !panelOpen;
    panel.classList.toggle('open', panelOpen);
    toggleBtn.classList.toggle('active', panelOpen);
  }
  toggleBtn.addEventListener('click', togglePanel);
  panel.classList.add('open');
  toggleBtn.classList.add('active');

  function updateStatus(s) {
    status.textContent = `${s.fps} fps · ${QUALITY[s.quality].label} · ${s.steps} steps · ${s.w}×${s.h} · ${DEBUG_NAMES[s.debug]}`;
  }

  function setParam(key, v) {
    const p = PARAMS.find(x => x.key === key);
    if (!p) return;
    const input = panel.querySelector(`input[type=range]`); // fallback below
    // find the matching input by value range
    panel.querySelectorAll('input[type=range]').forEach(inp => {
      if (parseFloat(inp.min) === p.min && parseFloat(inp.max) === p.max && parseFloat(inp.step) === p.step) {
        inp.value = v;
        const val = inp.parentElement.querySelector('.hud-val');
        if (val) val.textContent = fmt(v, p.step);
      }
    });
  }

  return {
    updateStatus, setParam, syncDebug, syncQuality, syncPreset, syncPlay, syncCine, syncMusic,
    togglePanel,
    setDebug: (d) => { state.debug = d; syncDebug(); },
    setQuality: (q) => { state.quality = q; syncQuality(); },
    setPreset: (i) => { state.preset = i; syncPreset(); },
    setPlaying: (b) => { state.playing = b; syncPlay(); },
    setCinematic: (b) => { state.cinematic = b; syncCine(); },
    setMusic: (b) => { state.music = b; syncMusic(); },
    panel,
  };
}

function fmt(v, step) {
  if (step >= 1) return String(Math.round(v));
  const dec = step >= 0.1 ? 1 : step >= 0.01 ? 2 : 3;
  return v.toFixed(dec);
}

